/* @autogenerated */
package net.civeira.phylax.feature.observe.viewer;

import java.util.Locale;
import java.util.Map;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.template.page.application.PageDecorator;
import net.civeira.phylax.feature.template.page.domain.DecoratedPage;
import net.civeira.phylax.feature.template.page.domain.PageDecoration;

/**
 * Viewer page decorated with the themes of multitenant-documents: thin adapter over the shared
 * {@link PageDecorator}, like DecorateHtml of oidc.
 *
 * <p>
 * The page template is {@code observe.<variant>} (seeded {@code observe.app}); the layout is the
 * full window companion theme ({@code corporate-full}). The viewer is not tenant data, so the
 * global theme is always used. Without a layout, the standalone page of the viewer is used.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class DocumentsObservePage implements ObservePageGateway {

  private final PageDecorator decorator;
  private final @ConfigProperty(name = "app.observe.viewer.brand",
      defaultValue = "auto") String brand;

  @Override
  public String getFullPage(final String title, final String innerContent, final Locale locale,
      final String variant) {
    DecoratedPage page = decorator.decorate(PageDecoration.builder().title(title)
        .innerContent(innerContent).locale(locale).pageTemplate("observe." + variant).wide(true)
        .defaultTheme("corporate").variables(Map.of("observe_base", "/observe")).build());
    if (page.getHtml().isPresent()) {
      // Inside a layout: the viewer fits its container and hides its brand (the layout has one)
      String html = page.getHtml().get().replace("data-fit=\"auto\"", "data-fit=\"container\"");
      return "auto".equals(brand) ? html.replace("data-brand=\"auto\"", "data-brand=\"hide\"")
          : html;
    }
    String body = page.getBody().replace("data-fit=\"auto\"", "data-fit=\"viewport\"");
    return ObservePages.standalone(title, body, null == locale ? "en" : locale.getLanguage());
  }
}
